const webhook = $node['Webhook Trigger'].json.body || $node['Webhook Trigger'].json || {};
const fileBase64 = webhook.fileBase64 || webhook.pdfBase64;
if (!fileBase64) { throw new Error('Webhook payload does not contain fileBase64/pdfBase64'); }

return {
  json: { ...webhook },
  binary: {
    data: {
      data: fileBase64,
      mimeType: 'application/pdf',
      fileName: webhook.fileName || ('invoice-' + (webhook.invoiceIndex || 0) + '.pdf')
    }
  }
};

// Use rawOcrText from backend payload if available, otherwise fall back to OCR.space response
const webhookData = $node['Webhook Trigger'].json.body || $node['Webhook Trigger'].json || {};
const preExtractedText = webhookData.rawOcrText || '';

if (preExtractedText && preExtractedText.trim().length > 20) {
  // Backend already extracted text - skip OCR.space call
  return [{ json: { ocrText: preExtractedText.trim(), usedBackendOcr: true } }];
}

// Try to get OCR.space response
let ocrText = '';
try {
  const ocrResponse = $input.first().json;
  ocrText = (ocrResponse.ParsedResults && ocrResponse.ParsedResults[0]) ? ocrResponse.ParsedResults[0].ParsedText : '';
} catch(e) {}

return [{ json: { ocrText: ocrText || preExtractedText, usedBackendOcr: false } }];

return $input.all().map((item, index) => {
  const response = item.json;
  let aiContent = '';
  if (response.content?.[0]?.text) {
    aiContent = response.content[0].text;
  } else if (typeof response.output === 'string') {
    aiContent = response.output;
  } else if (typeof response.text === 'string') {
    aiContent = response.text;
  }
  aiContent = String(aiContent)
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  let extractedData = {};
  try {
    extractedData = JSON.parse(aiContent);
  } catch (error) {
    try {
      const firstBrace = aiContent.indexOf('{');
      const lastBrace = aiContent.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        extractedData = JSON.parse(aiContent.substring(firstBrace, lastBrace + 1));
      }
    } catch (secondError) {
      extractedData = {};
    }
  }
  const webhookBody = $node['Webhook Trigger'].json.body || $node['Webhook Trigger'].json || {};
  const ocrNode = $node['Merge OCR Text']?.json || {};
  const documentId = webhookBody.documentId || webhookBody.docId || 'unknown';
  const invoiceIndex = Number(webhookBody.invoiceIndex ?? item.json?.invoiceIndex ?? index);
  const invoiceCount = Number(webhookBody.invoiceCount ?? item.json?.invoiceCount ?? 1);
  const pageStart = webhookBody.pageStart ?? item.json?.pageStart ?? 1;
  const pageEnd = webhookBody.pageEnd ?? item.json?.pageEnd ?? 1;
  const invoiceId = webhookBody.invoiceId || (documentId + '-invoice-' + (invoiceIndex + 1));

  let publicApiBase = 'https://logistics-doc-automation.vercel.app';
  if (typeof process !== 'undefined' && process.env && process.env.APP_BASE_URL) {
    publicApiBase = process.env.APP_BASE_URL.replace(/\/+$/, '');
  } else if (webhookBody.callbackUrl && !webhookBody.callbackUrl.includes('localhost') && !webhookBody.callbackUrl.includes('127.0.0.1')) {
    const match = webhookBody.callbackUrl.match(/^(https?:\/\/[^\/]+)/);
    if (match) {
      publicApiBase = match[1];
    }
  }
  const dynamicCallbackUrl = publicApiBase + '/api/documents/' + documentId + '/extraction/callback';

  return {
    json: {
      invoiceId,
      invoiceIndex,
      invoiceCount,
      pageStart,
      pageEnd,
      documentId,
      rawOcrText: ocrNode.ocrText || webhookBody.rawOcrText || '',
      extractedData,
      callbackUrl: dynamicCallbackUrl,
      confidenceScores: { invoiceNumber: 0.95, totalAmount: 0.95 },
      overallConfidence: 0.95
    }
  };
});

const parsed = $node['Parse AI Response'].json;
return [{
  json: {
    success: true,
    invoiceIndex: parsed.invoiceIndex,
    invoiceCount: parsed.invoiceCount,
    invoiceId: parsed.invoiceId,
    pageStart: parsed.pageStart,
    pageEnd: parsed.pageEnd,
    extractedData: parsed.extractedData,
    rawOcrText: parsed.rawOcrText,
    confidenceScores: parsed.confidenceScores,
    overallConfidence: parsed.overallConfidence
  }
}];
